import shutil,json
W=Path(__file__).resolve().parent;R=W.parents[1]
SRC=R/'Отчет_ЛР5.docx';BACK=W/'Отчет_ЛР5 — до правок.docx';OUT=W/'Отчет_ЛР5 — исправленный.docx'
if not BACK.exists():shutil.copy2(SRC,BACK)
d=Document(BACK)
def level(p):
 return {'Heading 1':1,'Heading 2':2,'Heading 3':3}.get(p.style.name,0)
def body(p):
 p.style='Normal';f=p.paragraph_format
 f.first_line_indent=Mm(12.5);f.left_indent=Mm(0);f.right_indent=Mm(0)
 f.space_before=Pt(0);f.space_after=Pt(0);f.line_spacing=1
 f.page_break_before=False;f.keep_with_next=False;f.keep_together=False;f.widow_control=True
 for r in p.runs:r.font.name='Times New Roman';r.font.size=Pt(14);r.font.color.rgb=RGBColor(0,0,0)
def insert_before(e,text):
 el=OxmlElement('w:p');e.addprevious(el);p=Paragraph(el,d._body);p.text=text;body(p);return p
seen=False
for p in d.paragraphs:
 if p.text=='Введение' and level(p)==1:seen=True
 if not seen:continue
 for br in p._p.xpath('.//w:br[@w:type="page"]'):br.getparent().remove(br)
 lev=level(p);f=p.paragraph_format
 f.page_break_before=lev==1;f.keep_with_next=bool(lev);f.keep_together=bool(lev);f.widow_control=True
 if lev:
  f.space_before=Pt(0 if lev==1 else 18);f.space_after=Pt(18 if lev==1 else 12)
 else:
  if p._p.xpath('.//w:drawing') or p.text.startswith(('Рисунок ','Таблица ','Листинг ')):
   f.keep_with_next=True;f.keep_together=True
for name in ['Normal','Heading 1','Heading 2','Heading 3']:
 d.styles[name].paragraph_format.page_break_before=name=='Heading 1'
 d.styles[name].paragraph_format.keep_together=name!='Normal'
 d.styles[name].paragraph_format.keep_with_next=name!='Normal'

