for p in list(d.paragraphs):
 if not p.text.startswith('Рисунок '):continue
 number=p.text.split()[1];after=Paragraph(p._p.getnext(),d._body)
 if number in extra:after.add_run(' '+extra[number])
 if number=='4.4':
  after.text='Выбор кванта 80 для RR и CP согласуется с таблицами 4.2 и 4.3. Среднее CPU-время равно 62,5, пропускная способность — 0,016 для всех вариантов. При нулевой цене переключений одинаковый объём полезной работы сохраняет длительность обслуживания набора.'
  body(after)
 after.paragraph_format.keep_with_next=False;after.paragraph_format.keep_together=False;after.paragraph_format.widow_control=True
